  CONSTRAINT `AgentRun_agentId_fkey` FOREIGN KEY (`agentId`) REFERENCES `Agent` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Memory` (
  `id` VARCHAR(191) NOT NULL,
  `businessId` VARCHAR(191) NOT NULL,
  `agentId` VARCHAR(191) NULL,
  `kind` VARCHAR(191) NOT NULL,
  `content` VARCHAR(191) NOT NULL,
  `embedding` JSON NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `Memory_businessId_kind_idx` (`businessId`, `kind`),
  CONSTRAINT `Memory_agentId_fkey` FOREIGN KEY (`agentId`) REFERENCES `Agent` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Contact` (
  `id` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NOT NULL,
  `name` VARCHAR(191) NULL,
  `title` VARCHAR(191) NULL,
  `email` VARCHAR(191) NULL,
  `phone` VARCHAR(191) NULL,
  `whatsapp` VARCHAR(191) NULL,
  `linkedin` VARCHAR(191) NULL,
  `isPrimary` BOOLEAN NOT NULL DEFAULT 0,
  `sourceUrl` VARCHAR(191) NULL,
  `verified` BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  INDEX `Contact_leadId_idx` (`leadId`),
  CONSTRAINT `Contact_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Activity` (
  `id` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NOT NULL,
  `type` VARCHAR(191) NOT NULL,
  `detail` JSON NULL,
  `actor` VARCHAR(191) NOT NULL DEFAULT 'ai',
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `Activity_leadId_createdAt_idx` (`leadId`, `createdAt`),
  CONSTRAINT `Activity_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Message` (
  `id` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NOT NULL,
  `channel` ENUM('EMAIL','WHATSAPP','LINKEDIN','SMS','CALL') NOT NULL,
  `direction` ENUM('OUTBOUND','INBOUND') NOT NULL,
  `subject` VARCHAR(191) NULL,
  `body` VARCHAR(191) NOT NULL,
  `status` ENUM('QUEUED','SCHEDULED','SENT','DELIVERED','OPENED','REPLIED','BOUNCED','FAILED','SUPPRESSED') NOT NULL DEFAULT 'QUEUED',
  `providerId` VARCHAR(191) NULL,
  `openedAt` DATETIME(3) NULL,
  `repliedAt` DATETIME(3) NULL,
  `scheduledAt` DATETIME(3) NULL,
  `sentAt` DATETIME(3) NULL,
  `meta` JSON NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `Message_leadId_createdAt_idx` (`leadId`, `createdAt`),
  INDEX `Message_status_scheduledAt_idx` (`status`, `scheduledAt`),
  CONSTRAINT `Message_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Conversation` (
  `id` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NOT NULL,
  `channel` ENUM('EMAIL','WHATSAPP','LINKEDIN','SMS','CALL') NOT NULL,
  `state` ENUM('AI_HANDLING','HUMAN_HANDOFF','CLOSED') NOT NULL DEFAULT 'AI_HANDLING',
  `intent` VARCHAR(191) NULL,
  `summary` VARCHAR(191) NULL,
  `handoffReason` VARCHAR(191) NULL,
  `updatedAt` DATETIME(3) NOT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  CONSTRAINT `Conversation_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Meeting` (
  `id` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NOT NULL,
  `provider` VARCHAR(191) NOT NULL,
  `startsAt` DATETIME(3) NOT NULL,
  `endsAt` DATETIME(3) NOT NULL,
  `joinUrl` VARCHAR(191) NULL,
  `status` VARCHAR(191) NOT NULL DEFAULT 'scheduled',
  PRIMARY KEY (`id`),
  CONSTRAINT `Meeting_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `Call` (
  `id` VARCHAR(191) NOT NULL,
  `businessId` VARCHAR(191) NOT NULL,
  `leadId` VARCHAR(191) NULL,
  `direction` VARCHAR(191) NOT NULL DEFAULT 'inbound',
  `fromNumber` VARCHAR(191) NOT NULL,
  `toNumber` VARCHAR(191) NOT NULL,
  `provider` VARCHAR(191) NOT NULL DEFAULT 'twilio',
  `callSid` VARCHAR(191) NULL,
  `status` VARCHAR(191) NOT NULL DEFAULT 'in_progress',
  `language` VARCHAR(191) NULL,
  `recordingUrl` VARCHAR(191) NULL,
  `transcript` JSON NULL,
  `summary` VARCHAR(191) NULL,
  `sentiment` VARCHAR(191) NULL,
  `intent` VARCHAR(191) NULL,
  `durationSec` INTEGER NULL,
  `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `endedAt` DATETIME(3) NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `Call_callSid_key` (`callSid`),
  INDEX `Call_businessId_startedAt_idx` (`businessId`, `startedAt`),
  CONSTRAINT `Call_leadId_fkey` FOREIGN KEY (`leadId`) REFERENCES `Lead` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Superadmin: manual payments + platform settings (payment methods)
CREATE TABLE IF NOT EXISTS `Payment` (
  `id` VARCHAR(191) NOT NULL,
  `tenantId` VARCHAR(191) NOT NULL,
  `amountCents` INTEGER NOT NULL,
  `currency` VARCHAR(191) NOT NULL DEFAULT 'USD',
  `method` VARCHAR(191) NOT NULL DEFAULT 'manual',
  `reference` VARCHAR(191) NULL,
  `note` VARCHAR(191) NULL,
  `plan` VARCHAR(191) NULL,
  `months` INTEGER NULL,
  `recordedBy` VARCHAR(191) NOT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `Payment_tenantId_createdAt_idx` (`tenantId`, `createdAt`),
  CONSTRAINT `Payment_tenantId_fkey` FOREIGN KEY (`tenantId`) REFERENCES `Tenant` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `PlatformSetting` (
  `key` VARCHAR(191) NOT NULL,
  `value` JSON NULL,
  `updatedAt` DATETIME(3) NOT NULL,
  PRIMARY KEY (`key`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
